(()=>{'use strict';const $=s=>document.querySelector(s);let snapshot=null,draft=null,baseRevision=0,dirty=false,busy=false,connected=false;
const scenes={focus:'小组聚焦',standings:'小组积分',thirdPlace:'第三名榜',prematch:'对阵前瞻',bracket:'完整赛程',knockoutFocus:'淘汰赛聚焦',postmatch:'赛后 MVP',schedule:'未来赛程',entrance:'入场动画',countdown:'独立倒计时',mapStats:'当图战绩',mapBP:'当局 BP'};
const types={replay:'Replay 半场精选',radar:'RadarHUD 半场回放',scoredeck:'ScoreDeck 展示',image:'图片',video:'视频',web:'自定义网页',none:'留空'};
const options=o=>Object.entries(o).map(([v,l])=>`<option value="${v}">${l}</option>`).join('');
for(const [side,title]of [['left','左侧展示'],['right','右侧展示']]){const el=document.createElement('div');el.className='slot-edit';el.innerHTML=`<h3>${title}</h3><div class="grid"><label>内容<select data-path="${side}.type">${options(types)}</select></label><label>画面适配<select data-path="${side}.fit"><option value="contain">完整显示</option><option value="cover">裁切铺满</option><option value="fill">拉伸铺满</option></select></label><label data-for="scoredeck">ScoreDeck 页面<select data-path="${side}.scene">${options(scenes)}</select></label><label data-for="image video web">素材 / 网页地址<input data-path="${side}.source" placeholder="http://…"></label><label data-for="image video">导入素材<input type="file" data-upload="${side}.source" accept="image/png,image/jpeg,image/webp,video/mp4,video/webm"></label><label data-for="radar scoredeck image video web">标签文字<input data-path="${side}.label" maxlength="40"></label><label class="check" data-for="radar scoredeck image video web"><input type="checkbox" data-path="${side}.showLabel">显示标签</label><label class="check" data-for="replay video"><input type="checkbox" data-path="${side}.muted">静音</label><label class="check" data-for="replay video radar"><input type="checkbox" data-path="${side}.loop">循环播放</label><label data-for="replay video radar">播放速度<select data-path="${side}.speed"><option value="0.5">0.5×</option><option value="1">1×</option><option value="1.5">1.5×</option><option value="2">2×</option><option value="4">4×</option></select></label><label data-for="radar">半场<select data-path="${side}.half"><option value="1">上半场（1–12）</option><option value="2">下半场（13–24）</option></select></label><label data-for="radar">地图楼层<select data-path="${side}.layer"><option value="all">全部</option><option value="low">1 层</option><option value="high">2 层</option></select></label><label data-for="radar">轨迹保留（秒，0 为关闭）<input type="number" data-path="${side}.fade" min="0" max="60"></label><label class="check" data-for="radar"><input type="checkbox" data-path="${side}.showPlayers">显示选手位置</label></div><small data-for="web">网页独立运行；其声音、播放及暂停由该网页自身控制。</small><small data-for="replay">按 Replay「半场精选」顺序播放；播放时钟独立。</small>`;el.dataset.side=side;$('#slot-controls').append(el);}
for(const [k,l]of Object.entries({showRound:'轮次名称',showTitle:'中场标题',showTimer:'倒计时',showScore:'队伍与比分',showMap:'地图名称',showLogos:'队伍图标',decoration:'几何装饰',transparent:'透明背景'})){const label=document.createElement('label');label.className='check';label.innerHTML=`<input type="checkbox" data-path="${k}">${l}`;$('#visibility').append(label);}
const get=(o,p)=>p.split('.').reduce((a,k)=>a?.[k],o);function put(o,p,v){const a=p.split('.'),k=a.pop();a.reduce((a,k)=>a[k],o)[k]=v;}
function notice(s){$('#notice').textContent=s;}
function visibility(){for(const el of document.querySelectorAll('[data-side]')){const type=draft[el.dataset.side].type;const file=el.querySelector('[type=file]');file.accept=type==='image'?'image/png,image/jpeg,image/webp':'video/mp4,video/webm';for(const n of el.querySelectorAll('[data-for]'))n.hidden=!n.dataset.for.split(' ').includes(type);}}
function fill(){for(const input of document.querySelectorAll('[data-path]')){const v=get(draft,input.dataset.path);if(input.type==='checkbox')input.checked=!!v;else input.value=v??'';}visibility();}
function choices(s){for(const [selector,items,first]of [['#match',s.matches.map(m=>[m.id,[m.stage,m.round].filter(Boolean).join(' · ')]),'跟随当前主赛'],['.teams',s.teams.map(t=>[t.id,t.name]),'读取比赛队伍']])for(const select of document.querySelectorAll(selector)){const value=select.value;select.replaceChildren(new Option(first,''),...items.map(([v,l])=>new Option(l||v,v)));select.value=value;}}
function accept(s){if(snapshot&&s.config.revision<snapshot.config.revision&&s.serverEpoch===snapshot.serverEpoch)return;const previous=snapshot;snapshot=s;connected=true;$('#connection').textContent=dirty?'有未保存修改':'已连接';if(!draft||!dirty&&!busy){choices(s);draft=structuredClone(s.config);baseRevision=s.config.revision;fill();}if(dirty&&previous&&s.config.revision!==baseRevision)notice('其他操作已更新中场设置；请复制未保存内容后重新载入。');
 for(const b of document.querySelectorAll('[data-action]'))b.disabled=busy||!!s.obs?.run&&b.dataset.action!=='capture-score';$('#auto-status').textContent=s.auto?.error||s.obs?.error||s.obs?.run?.waitMessage||(s.auto?.active?(s.mode==='full'?'全场精选':'半场精选')+' · '+({preparing:'准备输出',playing:'OBS 正在播出',returning:'正在返回'}[s.obs?.run?.status]||'正在播出'):s.auto?.connected?'GSI 已连接 · 等待自动播出':'等待 GSI 连接');const status=$('#module-status');status.replaceChildren();for(const text of [`Replay：${s.replay.phase==='running'?'已启动':'未启动（可在 Replay 板块启动）'}`,`RadarHUD：${s.radar.running?'已启动':'未连接'}`]){const p=document.createElement('p');p.textContent=text;status.append(p);} }
async function refresh(){try{const r=await fetch('/api/halftime',{cache:'no-store'});if(!r.ok)throw Error();accept(await r.json());}catch{connected=false;$('#connection').textContent='连接中断';}}
function busyState(v){busy=v;for(const b of document.querySelectorAll('button')){if(b.closest('#obs-highlights'))continue;b.disabled=v||!!snapshot?.obs?.run&&!!b.dataset.action&&b.dataset.action!=='capture-score';}}
async function post(action,settings){return SDClient.request('/api/halftime',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,settings,expectedRevision:baseRevision})});}
async function save(){if(!draft)return;if(!dirty)return;const s=await post('settings',draft);dirty=false;baseRevision=s.config.revision;draft=structuredClone(s.config);accept(s);fill();notice('已保存');}
async function run(fn){if(busy)return;busyState(true);try{await fn();}catch(e){notice(e.message);}finally{busyState(false);}}
$('#save').onclick=()=>run(save);
for(const b of document.querySelectorAll('[data-action]'))b.onclick=()=>run(async()=>{await save();const s=await post(b.dataset.action);baseRevision=s.config.revision;draft=structuredClone(s.config);dirty=false;accept(s);fill();notice(b.textContent+'：已执行');});
document.addEventListener('input',e=>{const input=e.target;if(!input.dataset.path||!draft)return;let value=input.type==='checkbox'?input.checked:input.value;if(input.type==='number'||['mapIndex','half','speed'].includes(input.dataset.path.split('.').at(-1)))value=Number(value);put(draft,input.dataset.path,value);dirty=true;$('#connection').textContent='有未保存修改';visibility();});
document.addEventListener('change',e=>{const input=e.target;if(input.tagName==='SELECT')input.dispatchEvent(new Event('input',{bubbles:true}));if(input.dataset.upload&&input.files?.[0])run(async()=>{const file=input.files[0],r=await SDClient.request('/api/halftime/media',{method:'POST',headers:{'Content-Type':file.type},body:file});put(draft,input.dataset.upload,r.url);dirty=true;fill();notice('素材已导入，保存后播出');input.value='';});});
$('#swap').onclick=()=>{[draft.left,draft.right]=[draft.right,draft.left];dirty=true;fill();notice('左右展示已交换，保存后播出');};
$('#copy-auto').onclick=async()=>{const u=new URL('/output/halftime-auto?obs=1',location.origin);if(!['localhost','127.0.0.1','[::1]'].includes(u.hostname)){const key=SDClient.authHeaders()['X-ScoreDeck-Key'];if(key)u.searchParams.set('key',key);}try{await navigator.clipboard.writeText(u.href);notice('已复制：'+u.href);}catch{notice(u.href);}};
for(const b of document.querySelectorAll('[data-program]'))b.onclick=()=>run(async()=>{await save();const s=await SDClient.request('/api/halftime/program',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:b.dataset.program,expectedRevision:baseRevision})});baseRevision=s.config.revision;draft=structuredClone(s.config);dirty=false;accept(s);fill();notice('播出状态已更新');});
$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(location.origin+'/output/halftime');notice('已复制 OBS 地址');}catch{notice(location.origin+'/output/halftime');}};$('#open').onclick=()=>window.open('/output/halftime','_blank','noopener');
addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
setInterval(()=>{if(!snapshot)return;const c=snapshot.config.clock;const now=SDClient.now(),s=Math.ceil(Math.max(0,c.status==='running'?c.endAt-now:c.remainingMs)/1000);$('#clock').textContent=String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');},100);
refresh();setInterval(refresh,2000);SDClient.subscribe(state=>{if(state)refresh();});
})();
